"""Builds the Android project folder (android_build) from index.html and icon.png.
GitHub runs this for you. It needs no extra installs."""
import os, shutil, sys

for needed in ("index.html", "icon.png"):
    if not os.path.isfile(needed):
        print("MISSING FILE: " + needed + " - upload it to the main page of the repository")
        sys.exit(1)

